SELECT id AS "id!: UploadId", attempt_id AS "attempt_id!: AttemptId", lease_generation AS "lease_generation!", token_hash AS "token_hash!", role AS "role!", backend AS "backend!", bucket AS "bucket!", key AS "key!", declared_size AS "declared_size!", declared_sha256 AS "declared_sha256!", media_type AS "media_type!", state AS "state!", expires_at AS "expires_at!: Timestamp", job_id AS "job_id?: JobId", interface AS "interface?", transfer AS "transfer!", multipart_upload_id AS "multipart_upload_id?", part_size AS "part_size?", urls_expire_at AS "urls_expire_at?: Timestamp" FROM uploads WHERE id = $1